const LEGAL_UPDATED = {"en": "Last updated: 27/09/2026", "no": "Sist oppdatert: 27.09.2026", "da": "Senest opdateret: 27.09.2026", "sv": "Senast uppdaterad: 2026-09-27", "fi": "Viimeksi päivitetty: 27.9.2026", "de": "Zuletzt aktualisiert: 27.09.2026", "nl": "Laatst bijgewerkt: 27-09-2026", "fr": "Dernière mise à jour : 27/09/2026", "es": "Última actualización: 27/09/2026", "it": "Ultimo aggiornamento: 27/09/2026", "pl": "Ostatnia aktualizacja: 27.09.2026", "pt": "Última atualização: 27/09/2026"};

const args = process.argv.slice(2);
const DRY = args.includes('--dry-run');
const FORCE = args.includes('--force');
const root = process.cwd();
const sha = (buf) => crypto.createHash('sha256').update(buf).digest('hex');

function die(msg) {
  console.error(`\n✖ ${msg}\n`);
  process.exit(1);
}

// ── Sanity: are we in the Qup Pulse project? ────────────────────────────────
let pkg;
try {
  pkg = JSON.parse(fs.readFileSync(path.join(root, 'package.json'), 'utf8'));
} catch {
  die('No package.json here. Run this from the root of qup-pulse-admin.');
}
if (pkg.name !== 'qup-pulse-admin') die(`package.json name is "${pkg.name}", expected "qup-pulse-admin".`);


const stamp = new Date().toISOString().replace(/[:.]/g, '-');
const backupDir = path.join(root, '.calls-backup', stamp);
function backup(rel) {
  const src = path.join(root, rel);
  if (!fs.existsSync(src) || DRY) return;
  const dst = path.join(backupDir, rel);
  fs.mkdirSync(path.dirname(dst), { recursive: true });
  fs.copyFileSync(src, dst);
}
function write(rel, content) {
  if (DRY) return;
  const abs = path.join(root, rel);
  fs.mkdirSync(path.dirname(abs), { recursive: true });
  fs.writeFileSync(abs, content);
}

const done = [], skipped = [], conflicts = [];

// ── Code files ──────────────────────────────────────────────────────────────
for (const f of FILES) {
  const abs = path.join(root, f.path);
  const exists = fs.existsSync(abs);
  const current = exists ? fs.readFileSync(abs) : null;
  if (current && sha(current) === sha(Buffer.from(f.content))) {
    skipped.push(`${f.path} (already up to date)`);
    continue;
  }
  const known = !exists || f.known.includes(sha(current));
  if (!known && !FORCE) {
    conflicts.push(f.path);
    continue;
  }
  backup(f.path);
  write(f.path, f.content);
  done.push(`${f.path}${exists ? '' : ' (new)'}${known ? '' : ' (forced)'}`);
}

// ── Legal: bump the "updated" date the privacy page shows ─────────────────
for (const [lang, updated] of Object.entries(LEGAL_UPDATED)) {
  const rel = `src/content/legal/${lang}.json`;
  const abs = path.join(root, rel);
  if (!fs.existsSync(abs)) { conflicts.push(`${rel} (missing)`); continue; }
  const raw = fs.readFileSync(abs, 'utf8');
  let data;
  try { data = JSON.parse(raw); } catch { conflicts.push(`${rel} (invalid JSON)`); continue; }
  if (data.updated === updated) { skipped.push(`${rel} (already up to date)`); continue; }
  data.updated = updated;
  backup(rel);
  write(rel, JSON.stringify(data, null, 2) + (raw.endsWith('\n') ? '\n' : ''));
  done.push(rel);
}

// ── Translations: set app.calls, leave everything else untouched ──────────
for (const [lang, calls] of Object.entries(LOCALES)) {
  const rel = `src/content/locales/${lang}.json`;
  const abs = path.join(root, rel);
  if (!fs.existsSync(abs)) { conflicts.push(`${rel} (missing)`); continue; }
  const raw = fs.readFileSync(abs, 'utf8');
  let data;
  try { data = JSON.parse(raw); } catch { conflicts.push(`${rel} (invalid JSON)`); continue; }
  if (!data.app || typeof data.app !== 'object') { conflicts.push(`${rel} (no "app" section)`); continue; }
  if (JSON.stringify(data.app.calls) === JSON.stringify(calls)) { skipped.push(`${rel} (already up to date)`); continue; }
  data.app.calls = calls;
  backup(rel);
  write(rel, JSON.stringify(data, null, 2) + (raw.endsWith('\n') ? '\n' : ''));
  done.push(rel);
}

// ── Report ──────────────────────────────────────────────────────────────────
console.log(`\n${DRY ? 'DRY RUN — nothing written.\n' : ''}`);
if (done.length) console.log(`✔ ${DRY ? 'Would update' : 'Updated'} ${done.length} file(s):\n  ` + done.join('\n  '));
if (skipped.length) console.log(`\n• Skipped:\n  ` + skipped.join('\n  '));
if (conflicts.length) {
  console.log(
    `\n⚠ Not changed — these differ from the version this script was written for\n` +
    `  (you've probably edited them since). Re-run with --force to overwrite\n` +
    `  (a backup is still made), or merge by hand:\n  ` + conflicts.join('\n  '),
  );
}
if (!DRY && done.length) console.log(`\nBackups: ${path.relative(root, backupDir)}/`);

console.log(`
Next steps:
  1. npm run dev → open a thread with someone you've both messaged → 🎥
     (camera/mic need https or localhost)
  2. Test web <-> phone: call from the app, answer in the browser, and back
  3. Commit and deploy quppulse.com
`);
process.exit(conflicts.length && !FORCE ? 2 : 0);
